-- Schema only; no production records or credentials.
CREATE TABLE work_entries (   id INTEGER PRIMARY KEY AUTOINCREMENT,   clerk_user_id TEXT NOT NULL,   work_date TEXT NOT NULL,   start_time TEXT NOT NULL,   end_time TEXT NOT NULL,   break_minutes INTEGER NOT NULL DEFAULT 0,   work_minutes INTEGER NOT NULL,   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE performance_entries (   id INTEGER PRIMARY KEY AUTOINCREMENT,   clerk_user_id TEXT NOT NULL,   work_date TEXT NOT NULL,   appointments INTEGER NOT NULL DEFAULT 0,   commissionable_appointments INTEGER NOT NULL DEFAULT 0,   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP , work_entry_id INTEGER);
CREATE TABLE office_members (   clerk_user_id TEXT PRIMARY KEY,   display_name TEXT,   email TEXT,   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE office_tasks (   id INTEGER PRIMARY KEY AUTOINCREMENT,   assigned_to TEXT NOT NULL,   created_by TEXT NOT NULL,   title TEXT NOT NULL,   description TEXT,   due_date TEXT,   priority TEXT NOT NULL DEFAULT 'normal',   status TEXT NOT NULL DEFAULT 'open',   completed_at TEXT,   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE monthly_closings (   id INTEGER PRIMARY KEY AUTOINCREMENT,   clerk_user_id TEXT NOT NULL,   payroll_month TEXT NOT NULL,   work_minutes INTEGER NOT NULL DEFAULT 0,   work_days INTEGER NOT NULL DEFAULT 0,   appointments INTEGER NOT NULL DEFAULT 0,   commissionable_appointments INTEGER NOT NULL DEFAULT 0,   hourly_rate_cents INTEGER NOT NULL,   commission_rate_cents INTEGER NOT NULL,   gross_cents INTEGER NOT NULL,   employee_deductions_cents INTEGER NOT NULL,   net_cents INTEGER NOT NULL,   employer_contributions_cents INTEGER NOT NULL,   employer_cost_cents INTEGER NOT NULL,   snapshot_json TEXT NOT NULL,   closed_by TEXT NOT NULL,   closed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   UNIQUE(clerk_user_id, payroll_month) );
CREATE TABLE office_settings (id INTEGER PRIMARY KEY CHECK (id = 1), goal_hours INTEGER NOT NULL DEFAULT 24, goal_appointments INTEGER NOT NULL DEFAULT 40, cut_appointments INTEGER NOT NULL DEFAULT 50, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE office_employer (   id INTEGER PRIMARY KEY,   name TEXT,   street TEXT,   zip_city TEXT,   company_number TEXT,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP , uv_carrier TEXT, uv_member_number TEXT, uv_tariff TEXT);
CREATE TABLE employee_profiles (   clerk_user_id TEXT PRIMARY KEY,   full_name TEXT,   personnel_number TEXT,   street TEXT,   zip_city TEXT,   birth_date TEXT,   insurance_number TEXT,   start_date TEXT,   end_date TEXT,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP , tax_id TEXT, health_insurance TEXT, iban TEXT, nationality TEXT, activity_key TEXT, other_employment TEXT, registered_at TEXT);
CREATE TABLE office_calls (   id INTEGER PRIMARY KEY AUTOINCREMENT,   assigned_to TEXT NOT NULL,   customer_name TEXT NOT NULL,   phones TEXT NOT NULL DEFAULT '[]',   branch_id INTEGER,   teams INTEGER NOT NULL DEFAULT 0,   briefing TEXT,   attempts INTEGER NOT NULL DEFAULT 0,   attempt_log TEXT NOT NULL DEFAULT '[]',   bad_phones TEXT NOT NULL DEFAULT '[]',   status TEXT NOT NULL DEFAULT 'open',   protocol TEXT,   closed_at TEXT,   archived_at TEXT,   created_by TEXT NOT NULL,   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP , hold_note TEXT, held_at TEXT, kk_state TEXT, kk_archived_at TEXT, rounds INTEGER NOT NULL DEFAULT 1, round_log TEXT NOT NULL DEFAULT '[]', fk_task_id INTEGER, topics TEXT, salutation TEXT);
CREATE TABLE employee_absences (   id INTEGER PRIMARY KEY AUTOINCREMENT,   clerk_user_id TEXT NOT NULL,   absence_date TEXT NOT NULL,   absence_type TEXT NOT NULL CHECK (absence_type IN ('vacation','sick','holiday','paid_leave')),   paid_minutes INTEGER NOT NULL DEFAULT 0 CHECK (paid_minutes >= 0),   paid_amount_cents INTEGER NOT NULL DEFAULT 0 CHECK (paid_amount_cents >= 0),   note TEXT,   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   UNIQUE (clerk_user_id, absence_date) );
CREATE TABLE payroll_settings(clerk_user_id TEXT PRIMARY KEY,employee_rv INTEGER DEFAULT 0,rv_min_base_applies INTEGER DEFAULT 0,flat_tax INTEGER DEFAULT 1,flat_tax_employee INTEGER DEFAULT 0,employer_kv INTEGER DEFAULT 1,employer_rv INTEGER DEFAULT 1,u1 INTEGER DEFAULT 1,u2 INTEGER DEFAULT 1,insolvency INTEGER DEFAULT 1,accident INTEGER DEFAULT 0,accident_rate REAL DEFAULT 0,accident_rate_estimate REAL DEFAULT 0,updated_at TEXT);

CREATE UNIQUE INDEX performance_work_once ON performance_entries(work_entry_id);
